package JavaCoreExercise;

public class DataType {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int age = 21;
        float percentage = 85.5f;
        double pi = 3.14159265359;
        char grade = 'A';
        boolean isPass = true;

        System.out.println("Integer value: " + age);
        System.out.println("Float value: " + percentage);
        System.out.println("Double value: " + pi);
        System.out.println("Character value: " + grade);
        System.out.println("Boolean value: " + isPass);
	}

}
